<?php require dirname(__DIR__,2).'/app/admin_view.php';admin_header('templates','Template marketplace'); ?>
<section class="card"><h2>Template catalog</h2><p>Upload a protected source ZIP before enabling purchases. Prices are in EUR.</p><button class="btn" id="new-template">New template</button><div id="templates"></div><form id="editor" class="card"><input type="hidden" name="id"><label>Title<input class="input" name="name" required maxlength="180"></label><label>Category<select class="input" name="category"><option>Website</option><option>App</option><option>Ecommerce</option><option>MusicArtist</option></select></label><label>Tech stack tags<input class="input" name="stack"></label><label>Price EUR<input class="input" name="price" type="number" min="0" step=".01" required></label><label>Description<textarea class="input" name="description"></textarea></label><label>Live demo URL<input class="input" name="demo_url" type="url"></label><label>Thumbnail<input class="input" id="thumbnail-file" type="file" accept="image/jpeg,image/png,image/webp"></label><input name="thumbnail" type="hidden"><label>Protected source ZIP<input class="input" id="source-file" type="file" accept=".zip"></label><input name="source_media_id" type="hidden"><label><input name="active" type="checkbox">Enable purchases</label><button class="btn primary">Save template</button><p id="template-status" role="status"></p></form></section>
<script>
let templates=[],token='';const form=document.getElementById('editor'),statusEl=document.getElementById('template-status');async function loadTemplates(){const r=await fetch('/api/templates.php'),d=await r.json();if(!r.ok){statusEl.textContent=d.error;return}templates=d.templates;token=d.csrf;const root=document.getElementById('templates');root.replaceChildren();for(const t of templates){const button=document.createElement('button');button.className='btn';button.textContent=t.name+' · EUR '+t.price+(Number(t.active)?' · Active':' · Disabled');button.onclick=()=>{form.reset();for(const key of ['id','name','category','stack','price','description','demo_url','thumbnail','source_media_id'])form.elements[key].value=t[key]||'';form.elements.active.checked=!!Number(t.active)};root.append(button)}}document.getElementById('new-template').onclick=()=>{form.reset();form.elements.id.value='';form.elements.source_media_id.value='';form.elements.thumbnail.value=''};form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;statusEl.textContent='Saving…';try{const source=document.getElementById('source-file').files[0],image=document.getElementById('thumbnail-file').files[0];if(source){const body=new FormData();body.append('media',source);body.append('kind','template-source');const r=await fetch('/api/music-media.php',{method:'POST',headers:{'X-CSRF-Token':token},body}),d=await r.json();if(!r.ok)throw Error(d.error);form.elements.source_media_id.value=d.id}if(image){const body=new FormData();body.append('image',image);const r=await fetch('/api/admin-upload.php',{method:'POST',headers:{'X-CSRF-Token':token},body}),d=await r.json();if(!r.ok)throw Error(d.error);form.elements.thumbnail.value=d.url}const r=await fetch('/api/templates.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':token},body:JSON.stringify({...Object.fromEntries(new FormData(form)),active:form.elements.active.checked})}),d=await r.json();if(!r.ok)throw Error(d.error);form.elements.id.value=d.id;statusEl.textContent='Saved';await loadTemplates()}catch(e){statusEl.textContent=e.message}finally{button.disabled=false}};loadTemplates();
</script><?php admin_footer(); ?>
